new_valid = '''LABEL_RE = re.compile(r"[A-Za-z0-9_-]{1,63}\\Z")


def valid_name(s):
    """Return canonical (lowercased) name, or None if invalid."""
    if not isinstance(s, str):
        return None
    if s == ".":
        return "."
    if not s.endswith("."):
        return None
    body = s[:-1]
    if body == "":
        return None
    labels = body.split(".")
    wire = 1  # root byte
    for lab in labels:
        if lab == "":
            return None
        if lab != "*":
            if LABEL_RE.fullmatch(lab) is None:
                return None
        wire += len(lab) + 1
    if wire > 255:
        return None
    return s.lower()
'''
assert old_valid in s
s=s.replace(old_valid,new_valid)

