new_depth='''def check_depth(root):
    # Count nested object/array containers; root container is depth 1.
    # Iterative DFS with per-level iterators: memory O(depth), not O(width).
    if not isinstance(root, (dict, list)):
        return True
    if 1 > 32:
        return False
    stack = [(iter(root.values() if isinstance(root, dict) else root), 1)]
    while stack:
        it, d = stack[-1]
        try:
            node = next(it)
        except StopIteration:
            stack.pop()
            continue
        if isinstance(node, (dict, list)):
            if d + 1 > 32:
                return False
            stack.append((iter(node.values() if isinstance(node, dict) else node), d + 1))
    return True
'''
